const item = $input.first().json;
const trace_id = 'castuo-ag-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const body = item.body ?? item;
const targetTerpene = String(body.target_terpene ?? $env.TERPENE_PROFILE ?? $env.CASTUO_TARGET_TERPENE ?? 'mirceno').trim().toLowerCase();
const ndvi = Number(body.ndvi_mean ?? body.ndvi ?? 0.6);
const current = {
  humedad: Number(body.humedad ?? 65),
  ph: Number(body.ph ?? 5.8),
  ec: Number(body.ec ?? 1.2),
  luz_umol: Number.isFinite(Number(body.luz_umol)) ? Number(body.luz_umol) : Math.min(1800, Math.max(200, ndvi * 1800)),
  uvb_ratio: Number(body.uvb_ratio ?? 0.05),
};
const optimal = {
  mirceno: { luz_umol: [800, 1200], ph: [5.8, 6.2], ec: [1.0, 1.6], uvb_ratio: 0.05 },
  limoneno: { luz_umol: [600, 900], ph: [6.0, 6.5], ec: [1.2, 1.8], uvb_ratio: 0.02 },
};
const p = optimal[targetTerpene] || optimal.mirceno;
const deviation = {
  luz_umol: current.luz_umol < p.luz_umol[0] || current.luz_umol > p.luz_umol[1],
  ph: current.ph < p.ph[0] || current.ph > p.ph[1],
  ec: current.ec < p.ec[0] || current.ec > p.ec[1],
  uvb_ratio: Math.abs(current.uvb_ratio - p.uvb_ratio) > 0.01,
};
const deviationAny = Object.values(deviation).some(Boolean);
const alertText = `[trace=${trace_id}] ALERTA agrotech (no medicina) perfil ${targetTerpene} | luz=${current.luz_umol} ph=${current.ph} ec=${current.ec} uvb=${current.uvb_ratio}`;
const ethics_notice = String($env.CASTUO_ALERT_LEGAL_PREFIX || 'TRL-6 integración | SNN capa TRL-4 sim').trim();
const trl_level = String($env.TRL_LEVEL || 'TRL-6-staging').trim();
return [{ json: { trace_id, trl_level, ethics_notice, target_terpene: targetTerpene, ndvi, current, optimal_profile: p, deviation, deviation_any: deviationAny, alert_text: alertText } }];
